INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运二年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb9d5570b796ecf7a4a202bff72b905f6cd3ff0c/content/books/zizhi-tongjian/vol-285/year-0945/part-03/sources/library/jiuwudaishi-084-945-december/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年十二月，段落 jiu-wudaishi-205deb4a7860-p002032；已回查上下文，电子底本原字保留，纸本及异文待核。", "id": "d9519df7-4fd3-5749-9e0d-adfc6634c215"}, {"title": "旧五代史·卷89·桑维翰传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb9d5570b796ecf7a4a202bff72b905f6cd3ff0c/content/books/zizhi-tongjian/vol-285/year-0945/part-03/sources/library/jiuwudaishi-089-sang-dismissal/source.txt", "note": "《旧五代史》卷89·桑维翰传，段落 jiu-wudaishi-205deb4a7860-p002134；已回查上下文，电子底本原字保留，纸本及异文待核。", "id": "0b26bfb4-879a-5210-8ca2-4ab701ce213e"}, {"title": "旧五代史·卷89·殷鹏传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb9d5570b796ecf7a4a202bff72b905f6cd3ff0c/content/books/zizhi-tongjian/vol-285/year-0945/part-03/sources/library/jiuwudaishi-089-yin-peng/source.txt", "note": "《旧五代史》卷89·殷鹏传，段落 jiu-wudaishi-205deb4a7860-p002146；已回查上下文，电子底本原字保留，纸本及异文待核。", "id": "c506b60d-55cd-5172-ae3c-822bf87720bf"}, {"title": "旧五代史·卷133·世袭列传二·楚马氏·戴偃事迹", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb9d5570b796ecf7a4a202bff72b905f6cd3ff0c/content/books/zizhi-tongjian/vol-285/year-0945/part-03/sources/library/jiuwudaishi-133-dai-yan/source.txt", "note": "《旧五代史》卷133·世袭列传二·楚马氏·戴偃事迹，段落 jiu-wudaishi-205deb4a7860-p003153；已回查上下文，电子底本原字保留，纸本及异文待核。", "id": "38b0dd52-5843-5aec-97e0-682491f11e88"}, {"title": "资治通鉴·卷285·后晋纪六·开运二年十一月至十二月及后续", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/tongjian-285-945-november-december/source.txt", "note": "《资治通鉴》卷285·后晋纪六·开运二年十一月至十二月及后续，段落 zizhi-tongjian-a63549944a71-p003384；已核卷号传主，电子本及异文待纸本校核。", "id": "7f3abe80-c419-5cfb-87b7-588ae233b38c"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "新五代史·卷29·桑维翰传·冯玉李彦韬争权", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/xinwudaishi-029-sang-feng-strife/source.txt", "note": "《新五代史》卷29·桑维翰传·冯玉李彦韬争权，段落 xin-wudaishi-b08f244b9241-p001061；上下文、卷年与传主已校核，纸本及异文待核。", "id": "971dc8a0-75e9-5a4b-b734-f76cfb59d1e1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "殷鹏", "aliases": ["殷鵬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名人，字大举。《旧五代史》记他进士出身，曾为后唐闵帝幕僚，天福年间任中书舍人，与冯玉共事并替他草拟诏令。945年十二月任给事中、枢密直学士，参与冯玉的任官商议；《资治通鉴》记有人因此向他请托、送礼。生卒年本批未核。", "biography": null, "status": "draft", "id": "edc9d41e-a358-504c-aca5-e3d05c5ed74f"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "石重睿", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的幼子。942年石敬瑭病中让他拜见冯道，并由宦者抱入冯道怀中；史书解释为托付之意。石敬瑭去世后，大臣以多事为由拥立石重贵，石重睿未能继位。生卒年未载。", "biography": null, "status": "draft", "id": "361f2434-8f22-5818-b912-366e1a3e8af8"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "戴偃", "aliases": ["玄黄子", "玄黃子"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《旧五代史》记为金陵人，自称玄黄子，擅长以诗讽谏，唐末避乱到湖南。《资治通鉴》945年条称他为湘阴处士，因诗讽刺而被马希范囚禁；《旧五代史》另记马希范命他迁居碧湘湖，并禁止他人与其来往。两书处置细节分别保留，生卒年未核。", "biography": null, "status": "draft", "id": "e182b3fc-d38c-5789-8fe8-c5da8e839d38"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "丁思瑾", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚天策副都军使。945年十二月条下记他为戴偃受囚上书直谏，马希范削去他的官爵。生卒年未载；不与同年《旧五代史》所记晋左羽林统军丁审琪混同。", "biography": null, "status": "draft", "id": "a6506023-c147-518d-9c90-431f4e68574c"}, {"name": "谢仲宣", "aliases": ["謝仲宣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王徐景达的府属。945年十二月条下，他向徐景达提出宋齐丘是先帝旧交、不应弃置；徐景达转向李璟进言，随后受命去青阳召宋齐丘。生卒年未载。", "biography": null, "status": "draft", "id": "818dca86-df7a-5442-9767-dc3209fc6fab"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
